// Runtime model of Omit on a union: keyof (A | B) is only the COMMON keys.
const circle = { kind: "circle", radius: 3, id: 1 };
const square = { kind: "square", side: 4, id: 2 };
const union = [circle, square]; // stands for the type A | B

const omit = (obj, keys) =>
  Object.fromEntries(Object.entries(obj).filter(([k]) => !keys.includes(k)));

// Wrong: Omit<A | B, "id"> works on the union as a whole (common keys only)
const common = Object.keys(union[0]).filter((k) => union.every((v) => k in v));
const whole = common.filter((k) => k !== "id");
console.log("input:", JSON.stringify(union));
console.log("common keys of union:", common);
console.log("Omit on whole union keeps keys:", whole); // radius and side are lost

// Right: distribute, i.e. apply Omit to each member (T extends any ? Omit<T,K> : never)
const distributed = union.map((v) => omit(v, ["id"]));
console.log("distributed Omit:", JSON.stringify(distributed));
// Time O(members * keys), space O(members * keys)

// Runtime model of a distributive conditional type: T extends string ? true : false
// A union type is modeled as an array of member type names.
const isString = (member) => member === "string";

// Distributive: judge each member separately, then union the results
function distributive(union) {
  return [...new Set(union.map(isString))];
}
// Wrapped [T] extends [string]: judge the union as a whole
function wrapped(union) {
  return union.every(isString);
}

const inputs = [["string"], ["string", "number"], ["number"], []];
for (const u of inputs) {
  console.log(
    "T =", JSON.stringify(u),
    "| distributive ->", JSON.stringify(distributive(u)),
    "| wrapped ->", wrapped(u)
  );
}
// [] models never: distribution over zero members gives an empty union (never),
// while the wrapped form answers true because every() of nothing is true.
// Time O(n) per check, space O(n).

// Runtime twin of typed dotted paths: list all valid paths, with a depth limit,
// then read a value by path (what PathValue does at the type level).
const user = {
  name: "Ada",
  address: { city: "Paris", geo: { lat: 48.8, lng: 2.3 } },
  tags: ["x"],
};

// Like Paths<T>: K | `${K}.${Paths<T[K]>}`, with a depth counter to stop blow-ups
function paths(obj, depth = 3) {
  if (depth === 0 || typeof obj !== "object" || obj === null) return [];
  const out = [];
  for (const k of Object.keys(obj)) {
    out.push(k);
    for (const rest of paths(obj[k], depth - 1)) out.push(k + "." + rest);
  }
  return out;
}

// Like PathValue<T, P>: split at the first dot, recurse on the rest
function get(obj, path) {
  const i = path.indexOf(".");
  if (i === -1) return obj[path];
  return get(obj[path.slice(0, i)], path.slice(i + 1));
}

console.log("all paths:", paths(user));
console.log("depth 1 :", paths(user, 1));
console.log("address.geo.lat =", get(user, "address.geo.lat"));
console.log("address.city   =", get(user, "address.city"));
// Cost: path count grows with total properties, so wide objects give many paths.

// Template literal types model: unions in holes make a cross product.
const sizes = ["sm", "lg"];
const colors = ["red", "blue"];
const cross = sizes.flatMap((s) => colors.map((c) => `${s}-${c}`));
console.log("sizes x colors:", cross, "count =", cross.length);

// Growth is multiplicative, which is why TS caps unions at 100,000 members
const a = Array.from({ length: 10 }, (_, i) => "a" + i);
const b = Array.from({ length: 10 }, (_, i) => "b" + i);
const c = Array.from({ length: 10 }, (_, i) => "c" + i);
console.log("10 x 10 x 10 =", a.length * b.length * c.length, "literals");
console.log("50 x 50 x 50 =", 50 * 50 * 50, "literals (over the 100000 cap)");

// Parsing like `${infer H}.${infer R}`: infer H is the SHORTEST match (first dot)
function splitFirst(s) {
  const i = s.indexOf(".");
  return i === -1 ? [s] : [s.slice(0, i), s.slice(i + 1)];
}
// Last occurrence needs a recursive walk (or lastIndexOf at runtime)
function splitLast(s) {
  const i = s.lastIndexOf(".");
  return i === -1 ? [s] : [s.slice(0, i), s.slice(i + 1)];
}
console.log("first split:", splitFirst("a.b.c"));
console.log("last split :", splitLast("a.b.c"));
